def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n, name='x'), QuantumRegister(m, name='y')
    qc = QuantumCircuit(x, y)

    # Compute f(x) mod 2^m and store in y
    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

    # Apply a phase if y == L
    l_binary = bin(L)[2:].zfill(m)
    for i in range(m):
        if l_binary[m - 1 - i] == '0':
            qc.x(y[i])

    # Use an ancilla to store the result of the comparison (y == L)
    ancilla = QuantumRegister(1, name='ancilla')
    qc.add_register(ancilla)
    qc.mct(y, ancilla[0])

    # Apply the phase conditionally on the ancilla
    qc.p(theta, ancilla[0])

    # Uncompute the comparison and the f(x) calculation
    qc.mct(y, ancilla[0])
    for i in range(m):
        if l_binary[m - 1 - i] == '0':
            qc.x(y[i])

    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

