def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x = QuantumRegister(n, 'x')
    y = QuantumRegister(m, 'y')
    qc = QuantumCircuit(x, y)

    # Compute f(x) mod 2^m and store in y
    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

    # Apply a phase if y == L using a generalized gate
    comparison_circuit = QuantumCircuit(m)
    l_binary = bin(L)[2:].zfill(m)
    for i in range(m):
        if l_binary[m - 1 - i] == '0':
            comparison_circuit.x(i)

    # Apply phase gate
    qc.rz(theta, y)

    # Uncompute comparison_circuit
    inverse_comparison_circuit = comparison_circuit.inverse()
    qc.compose(inverse_comparison_circuit, qubits=y, inplace=True)

    # Uncompute f(x) mod 2^m
    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

    return qc

