def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    # Create a superposition of all possible states
    for i in range(n):
        qc.h(i)

    # Apply a multi-controlled Z gate where the control qubits are all but one
    # and the target is the remaining one.  This effectively marks states
    # that have only one qubit set to 1.  We use Deutch's Algorithm to 
    # efficiently implement the multi-controlled Z gate.

    for i in range(n):
        # Apply X to all qubits except i
        for j in range(n):
            if i != j:
                qc.x(j)

        # Apply multi-controlled Toffoli with all qubits as control except i,
        # and qubit i as target
        if n > 2:
            controls = [j for j in range(n) if j != i]
            qc.mcx(controls, i)

        elif n == 2:
            qc.cx(0 if i==1 else 1, i)

        # Unapply X to all qubits except i
        for j in range(n):
            if i != j:
                qc.x(j)

