    def adder(qc, a, n):
        for i in range(n):
            if (a >> i) & 1:
                for j in range(i, n):
                    qc.cx(j, j+1)

    def subtractor(qc, a, n):
        for i in reversed(range(n)):
            if (a >> i) & 1:
                for j in reversed(range(i, n)):
                    qc.cx(j, j+1)

    def comparator(qc, L, n):
