            if (L >> i) & 1:
                qc.x(i+1)
        for i in range(n):
            qc.mct(list(range(1, i+1)), n+1)
        for i in reversed(range(n)):
            if (L >> i) & 1:
                qc.x(i+1)

    def controlled_comparator(qc, L, n, control_qubit):
        for i in range(n):
            if (L >> i) & 1:
                qc.cx(control_qubit, i+1)
                qc.x(i+1)
        for i in range(n):
            control_qubits = [control_qubit] + list(range(1, i+1))
            qc.mct(control_qubits, n+1)
        for i in reversed(range(n)):
            if (L >> i) & 1:
                qc.x(i+1)
                qc.cx(control_qubit, i+1)


    adder(qc, a, n)
    controlled_comparator(qc, L, n, 0)
    subtractor(qc, L, n)
    controlled_comparator(qc, L, n, 0)
    adder(qc, L, n)
    subtractor(qc, a, n)

    return qc

