def compare_and_subtract(n, L):
    qc = QuantumCircuit(n + 1)

    # Compare with L using ripple carry addition based comparator
    carry = 0
    for i in range(n + 1):
        qc.x(i)  # Initial inversion
        if (L >> i) & 1:
            if carry == 0:
                qc.x(i)
            else:
                qc.cx(carry - 1, i)
        else:
            if carry > 0:
                qc.cx(carry - 1, i)
        if carry < n:
            carry = i + 1

    # Check if greater than or equal to L
    all_ones = True
    for i in range(n + 1):
        if (L >> i) & 1 == 0:
            all_ones = False
            break

    if all_ones:
         geq_L_flag = qc.num_qubits
    else:
        geq_L_flag = n + 1

    geq_L = QuantumCircuit(1)
    geq_L.x(0)
    qc.append(geq_L.to_gate(), [geq_L_flag-1])

    # Controlled subtraction of L
    for i in reversed(range(n + 1)):
        if (L >> i) & 1:
            qc.cx(geq_L_flag-1, i)

    # Reset comparator
    carry = 0
    for i in reversed(range(n + 1)):
        if (L >> i) & 1:
            if carry == 0:
                qc.x(i)
            else:
                qc.cx(carry - 1, i)
        else:
            if carry > 0:
                qc.cx(carry - 1, i)
        if carry < n:
            carry = i + 1

