        if (k_before >> i) & 1:
            qc.cx(i, n)

    # Apply g(m, k)
    qc.cx(n, 0)
    for i in range(1, n):
        qc.ccx(n, i, 0)

    for i in range(n):
        qc.cx(i, n)

    qc.cx(n, 0)
    for i in range(1, n):
        qc.ccx(n, i, 0)

    # Apply g(m_after, k_after)
    if m_after == 1:
        qc.x(n)
    for i in range(n):
        if (k_after >> i) & 1:
            qc.cx(i, n)

    return qc

from qiskit import QuantumCircuit


def solve(n: int, m_before: int, k_before: int, m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    # Calculate the XOR of m values
    m_xor = (m_before ^ m_after)

    # Calculate the sum of k values modulo 2^n
    k_sum = (k_before + k_after) % (2**n)

    # Apply g(m_before, k_before) and g(m_after, k_after)
    # This is equivalent to applying g(m_xor, k_sum)

    for i in range(n):
        if (k_before >> i) & 1:
            qc.cx(i, n)  # Apply Operation 1 (controlled by k_before)

    if m_before == 1:
        qc.cx(n, 0)  # Apply Operation 2 (controlled by m_before)

    qc.cx(n, 0)

    for i in range(n):
        qc.cx(i, n)

    for i in range(n):
        if (k_after >> i) & 1:
            qc.cx(i, n)  # Apply Operation 1 (controlled by k_after)

    if m_after == 1:
        qc.cx(n, 0)  # Apply Operation 2 (controlled by m_after)

    qc.cx(n, 0)

    for i in range(n):
        qc.cx(i, n)

    return qc
